//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:					HE_Watchdog
//	CREATOR:				Helgevold - Jan Magne Dybvik
// REQUIREMENTS: NX CPU
//
// DESCRTIPTION: 	Funksjonsblokken monitorer endring i enten Boolsk verdi når Cfg_UseNumber er FALSE eller en numerisk verdi når Cfg_UseNumber er TRUE.
//								Når Cfg_UseNumber er FALSE sjekkes Inp_Bool for endring, den sjekkes for Stigende og/eller fallende flanke. Valg av flanke konfigureres av Cfg_MonitorRising og Cfg_MonitorFalling.
//								Når Cfg_UseNumber er TRUE sjekkes Inp_Number for endring i verdi.
//								Når tiden siden endrig overstiger tiden konfigurert i Cfg_TimeOut vil Sts_Timeout bli TRUE.
//								Det er 3 utganger for diagnostikk, Val_TimeSinceTrigger som er tidens siden forrige endring, Val_LastSignalInterval som er tiden det tok for forrige endring og Val_LastTriggerTime som er tidspunktet for forrige endring.
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE					SIGN							DESCRIPTION
//	 1.0.0				2024-03-25			Jan Magne Dybvik		Initial release
//	 1.1.0				2024-03-26			Jan Magne Dybvik		Lagt til valg for numerisk input
//	 2.0.0				2026-05-07			William Veim				Rework, and added reset function
//	 2.1.0				2026-05-19			Ruben Byman				Added states for controlling counter and BOOL outputs
//
//================================================================================================================================

CASE Cfg_Type OF
	
	0: //Watchdog function of number value
	IF Wrk_Number_Sample = Inp_Number THEN
		Wrk_TimeSinceTrigger := ADD_TIME(In1 := Wrk_TimeSinceTrigger, In2 := GetMyTaskInterval());
	ELSE
		Wrk_TimeSinceTrigger := TIME#0s;
		Wrk_LastTriggerTime := GetTime();
	END_IF;
	
	Wrk_Number_Sample:= Inp_Number;
	
	1: //Watchdog bool value rising
	Wrk_BOOL_RE(Clk:=Inp_Bool);
	
	IF NOT Wrk_BOOL_RE.Q THEN
		Wrk_TimeSinceTrigger := ADD_TIME(In1 := Wrk_TimeSinceTrigger, In2 := GetMyTaskInterval());
	ELSE
		Wrk_TimeSinceTrigger := TIME#0s;
		Wrk_LastTriggerTime := GetTime();
	END_IF;
	
	2: //Watchdog bool value falling
	Wrk_BOOL_FE(Clk:=Inp_Bool);
	
	IF NOT Wrk_BOOL_FE.Q THEN
		Wrk_TimeSinceTrigger := ADD_TIME(In1 := Wrk_TimeSinceTrigger, In2 := GetMyTaskInterval());
	ELSE
		Wrk_TimeSinceTrigger := TIME#0s;
		Wrk_LastTriggerTime := GetTime();
	END_IF;
	
	3: //Control reset output
	Out_Reset:=	 Inp_Number >= Cfg_ResetValue;
	
	IF Wrk_Number_Sample = Inp_Number OR Inp_Number >= Cfg_ResetValue THEN
		Wrk_TimeSinceTrigger := ADD_TIME(In1 := Wrk_TimeSinceTrigger, In2 := GetMyTaskInterval());
	ELSE
		Wrk_TimeSinceTrigger := TIME#0s;
		Wrk_LastTriggerTime := GetTime();
	END_IF;
	
	4: //Control resettable counter output
	Wrk_TimeSinceLastHeartbeat:=ADD_TIME(In1:=Wrk_TimeSinceLastHeartbeat, In2:=GetMyTaskInterval());
	
	IF Wrk_TimeSinceLastHeartbeat > TIME#1s THEN
		Wrk_Counter:= Wrk_Counter+1;
		Wrk_TimeSinceLastHeartbeat:=	TIME#0s;
	END_IF;
	
	IF Inp_Reset THEN
		Wrk_Counter := 0;
		Wrk_TimeSinceLastHeartbeat:=	TIME#0s;
	END_IF;
	
	IF Wrk_Counter >= Cfg_ResetValue AND Cfg_ResetValue <> 0 THEN
		Wrk_TimeSinceTrigger := ADD_TIME(In1 := Wrk_TimeSinceTrigger, In2 := GetMyTaskInterval());
	ELSE
		Wrk_TimeSinceTrigger := TIME#0s;
		Wrk_LastTriggerTime := GetTime();
	END_IF;
	
	5: //Control BOOL output
	Wrk_TimeSinceLastHeartbeat:=ADD_TIME(In1:=Wrk_TimeSinceLastHeartbeat, In2:=GetMyTaskInterval());
	
	IF Wrk_TimeSinceLastHeartbeat > TIME#1s THEN
		Wrk_BOOL := NOT Wrk_BOOL;
		Wrk_TimeSinceLastHeartbeat:=	TIME#0s;
	END_IF;
	
	Wrk_TimeSinceTrigger := TIME#0s;
	
END_CASE;
 
 // Update outputs
Sts_Timeout := 					Wrk_TimeSinceTrigger >= Cfg_TimeOut;
Out_TimeSinceTrigger := 	Wrk_TimeSinceTrigger;
Out_LastTriggerTime := 		Wrk_LastTriggerTime;
Out_Counter :=					Wrk_Counter;
